/* Stages 5-6 lessons */
export const LESSONS_C={
'classes-objects':{intro:'A class is a blueprint; an object is one house built from it. Same plan, many homes with different paint.',question:'What is shared between all “books” yet different in each copy?',analogy:'Housing colony: blueprint Book (title, pages, borrow()). Your copy and mine share design, differ in state (borrowed or not).',analogyFail:'Where it breaks: blueprints do not store your books. Only objects hold real data — the class holds the design.',explain:['<b>class Book { }</b> defines fields (info) + methods (actions). <b>new Book()</b> builds one object.','<b>State</b> = current field values. <b>Behavior</b> = what methods do.','Dot uses it: <b>b.borrow()</b>. Different objects, independent state.'],code:`class Book {\n  String title;\n  boolean borrowed;\n  void borrow() { borrowed = true; }\n}\nBook b1 = new Book();\nb1.title = "Dune";\nb1.borrow();\nSystem.out.println(b1.title + " " + b1.borrowed);`,codeNotes:['Class = design.','new = build one.','b1 has its own state.'],output:'Dune true',why:'Object stores Dune + borrowed; method changed its state.',sim:{kind:'concat',label:'Two houses, different paint.',fields:[{v:'Dune'},{v:' (borrowed)'}]},mistakes:[{bad:'Book b; b.borrow();',why:'No house built (null).',fix:'b = new Book(); first.'},{bad:'“Class holds my book data”',why:'Design ≠ data.',fix:'Data lives in objects.'},{bad:'All in main, no classes',why:'Spaghetti.',fix:'Model things as classes.'}],practices:[{title:'Build 2 books',task:'Two books, borrow one. Other still free?',hint:'Independent state.',sol:'Yes — separate objects.'},{title:'Spot state/behavior',task:'title/borrowed vs borrow(): which is which?',hint:'Info vs action.',sol:'Fields = state; method = behavior.'}],quiz:[{id:'q1',prompt:'Class vs object?',options:[{t:'Blueprint vs one built thing',ok:true},{t:'Same thing'},{t:'Object vs blueprint (reversed)'},{t:'File vs folder'}],explain:'Plan vs house.'},{id:'q2',prompt:'new Book() does…',options:[{t:'Builds one object',ok:true},{t:'Deletes class'},{t:'Prints book'},{t:'Nothing'}],explain:'Construction.'},{id:'q3',prompt:'b1.borrow() affects b2?',options:[{t:'No — independent state',ok:true},{t:'Yes always'},{t:'Deletes b2'},{t:'Merges them'}],explain:'Separate houses.'}],takeaways:['Class = plan; object = instance.','State in fields; actions in methods.','new builds; dot uses.'],recall:'What lives in the class vs the object?',todo:'Model a Pen class with 2 fields + 1 method.',anim:{title:'Colony',steps:[{caption:'Blueprint Book (design only).',html:'<div class="pipe"><div class="box"><b>Book 📐</b><br>title · borrowed · borrow()</div></div>'},{caption:'Build b1 = new Book().',html:'<div class="pipe"><div class="box"><b>b1 🏠</b><br>Dune · free</div></div>'},{caption:'b1.borrow() → its flag flips.',html:'<div class="pipe"><div class="box"><b>b1 🏠</b><br>Dune · borrowed ✓</div></div>'}]}},
'fields-methods':{intro:'Fields remember; methods do. Together they make objects that guard their own data and offer useful actions.',question:'What should a vending machine remember vs do?',analogy:'Library card: fields = name, id, books held (memory). Methods = borrow(), returnBook() (actions that update memory safely).',analogyFail:'Where it breaks: cards do not validate themselves. Good methods do — reject borrow when limit reached.',explain:['<b>Fields</b>: variables inside class. Each object gets copies. <b>Methods</b>: functions inside class, can use fields directly.','Access via <b>dot</b>: b.title, b.borrow(). Inside methods, fields by name.','Keep fields meaningful; methods verb-named: borrow, returnBook, isAvailable.'],code:`class Book {\n  String title;\n  boolean borrowed;\n  boolean isAvailable() { return !borrowed; }\n  void borrow() { borrowed = true; }\n}\nBook b = new Book();\nb.title = "Dune";\nb.borrow();\nSystem.out.println(b.isAvailable());`,codeNotes:['isAvailable reads state.','borrow writes state.','Dot connects object + member.'],output:'false',why:'Borrowed true → !true = false: not available.',sim:{kind:'cond',label:'Available? try states.',fields:[{v:'18'}]},mistakes:[{bad:'Static-style call on class',why:'Need an object for instance members.',fix:'Book b = new...; b.borrow();'},{bad:'Public mutable everything',why:'Anyone corrupts.',fix:'Private + methods (next lessons).'},{bad:'Method does 5 jobs',why:'Untestable.',fix:'One job per method.'}],practices:[{title:'Add returnBook',task:'Write void returnBook() setting false.',hint:'Mirror borrow.',sol:'void returnBook(){ borrowed = false; }'},{title:'isAvailable trace',task:'New book (false) → available?',hint:'!false.',sol:'true.'}],quiz:[{id:'q1',prompt:'Fields are…',options:[{t:'Object memory (state)',ok:true},{t:'Actions'},{t:'Classes'},{t:'Files'}],explain:'Info held.'},{id:'q2',prompt:'b.borrow() is…',options:[{t:'Calling behavior on b',ok:true},{t:'Creating a class'},{t:'Deleting b'},{t:'A field'}],explain:'Dot + action.'},{id:'q3',prompt:'Output above?',options:[{t:'false',ok:true},{t:'true'},{t:'Dune'},{t:'Error'}],explain:'Borrowed → unavailable.'}],takeaways:['Fields = memory per object.','Methods = actions using memory.','Verb names for methods.'],recall:'Name one field and one method for a Student.',todo:'Add returnBook + test both.',anim:{title:'Card',steps:[{caption:'Card remembers: title, borrowed.',html:'<div class="viz"><div class="varbox"><div class="nm">title</div><div class="vl">Dune</div></div><div class="varbox"><div class="nm">borrowed</div><div class="vl">false</div></div></div>'},{caption:'borrow() acts: flips flag.',html:'<div class="viz"><div class="varbox"><div class="nm">borrowed</div><div class="vl">true ✨</div></div></div>'},{caption:'isAvailable() reports !borrowed.',html:'<div class="pipe"><div class="box">!true → false</div></div>'}]}},
'constructors':{intro:'Constructors are birth rituals: name + starting values in one call. No half-built objects.',question:'Why do phones force setup (language, PIN) on first boot?',analogy:'Birth certificate office: give name + birth data once, receive a valid citizen. new Book("Dune") = certificate with title stamped at birth.',analogyFail:'Where it breaks: certificates rarely change. Objects change after — constructor sets the start, not the forever.',explain:['<b>Same name as class, no return type</b>: Book(String t) { title = t; }. Called by <b>new</b>.','<b>Overload</b>: several constructors (no-arg, full). Chain with <b>this(...)</b>.','No constructor written? Java gives a free no-arg one. Add one → free one gone.'],code:`class Book {\n  String title; boolean borrowed;\n  Book(String t) { title = t; }\n  Book(String t, boolean b) { title = t; borrowed = b; }\n}\nBook b = new Book("Dune");\nSystem.out.println(b.title);`,codeNotes:['Two birth options.','new picks by arguments.','Object starts valid.'],output:'Dune',why:'Matched single-arg constructor; title stamped.',sim:{kind:'concat',label:'Birth stamp: title.',fields:[{v:'Dune'},{v:' (new)'}]},mistakes:[{bad:'void Book(...)',why:'That is a method, not constructor!',fix:'No return type at all.'},{bad:'Book b; (no new)',why:'Declared, not born.',fix:'b = new Book("X");'},{bad:'Adding constructor breaks new Book()',why:'Free one vanished.',fix:'Keep an explicit no-arg too.'}],practices:[{title:'Write no-arg',task:'Book() setting title "Untitled".',hint:'Same name, no return.',sol:'Book(){ title = "Untitled"; }'},{title:'Chain',task:'Make Book() call Book("Untitled").',hint:'this(...).',sol:'Book(){ this("Untitled"); }'}],quiz:[{id:'q1',prompt:'Constructor name…',options:[{t:'Same as class, no return type',ok:true},{t:'Anything + void'},{t:'main always'},{t:'lowercase'}],explain:'Birth signature.'},{id:'q2',prompt:'Called by…',options:[{t:'new',ok:true},{t:'Dot after'},{t:'Comments'},{t:'Import'}],explain:'new triggers it.'},{id:'q3',prompt:'Add any constructor: free no-arg…',options:[{t:'Disappears',ok:true},{t:'Stays'},{t:'Doubles'},{t:'Becomes private'}],explain:'Write your own no-arg if needed.'}],takeaways:['Birth ritual with starting data.','Overload for options; this() chains.','No return type — ever.'],recall:'How is a constructor different from a method?',todo:'Give your Pen class a constructor.',anim:{title:'Birth office',steps:[{caption:'Form: title = Dune.',html:'<div class="pipe"><div class="box">new Book("Dune")</div></div>'},{caption:'Officer stamps: constructor runs.',html:'<div class="pipe"><div class="box">Book(t) → title = t ✓</div></div>'},{caption:'Citizen issued, valid.',html:'<div class="pipe"><div class="box"><b>b1 🏠 Dune</b></div></div>'}]}},
'this-keyword':{intro:'this means “this object here”. It untangles “which title?” when parameters shadow fields.',question:'In “my bag is in my room”, who is “my”?',analogy:'Name tag “I”. In a crowd of Titles, this.title = MY title. Also this(...) calls my other constructor (sibling birth).',analogyFail:'Where it breaks: “I” outside a person is nonsense. this outside an object method/constructor is an error.',explain:['<b>this.title = title</b>: field = parameter. Fixes shadowing.','<b>this(...)</b> first line calls another constructor. <b>this.method()</b> explicit self-call (rare).','Use when names collide; otherwise optional.'],code:`class Book {\n  String title;\n  Book(String title) { this.title = title; }\n  void rename(String title) { this.title = title; }\n}\nBook b = new Book("Dune");\nb.rename("Dune 2");\nSystem.out.println(b.title);`,codeNotes:['this.title = field.','title alone = parameter.','Rename updates the field.'],output:'Dune 2',why:'Parameter assigned into the object’s field via this.',sim:{kind:'concat',label:'Whose title? this one.',fields:[{v:'Dune'},{v:' 2'}]},mistakes:[{bad:'title = title; (no this)',why:'Self-assigns parameter — field stays null!',fix:'this.title = title;'},{bad:'this in static main',why:'No “this object” there.',fix:'Create an object first.'},{bad:'this(...) not first line',why:'Must lead.',fix:'Put this(...) line 1.'}],practices:[{title:'Fix shadow',task:'Fix: Book(String title){ title = title; }',hint:'this.',sol:'this.title = title;'},{title:'Chain sib',task:'Book(){ this("X"); } — what happens?',hint:'Calls sibling.',sol:'Delegates to 1-arg version.'}],quiz:[{id:'q1',prompt:'this.title means…',options:[{t:'This object’s field',ok:true},{t:'The parameter'},{t:'A static'},{t:'A class'}],explain:'Self reference.'},{id:'q2',prompt:'title = title without this…',options:[{t:'Parameter self-assign; field unchanged',ok:true},{t:'Works fine'},{t:'Error always'},{t:'Deletes object'}],explain:'Shadow trap.'},{id:'q3',prompt:'this(...) must be…',options:[{t:'First line',ok:true},{t:'Last line'},{t:'Anywhere'},{t:'Outside'}],explain:'Delegation leads.'}],takeaways:['this = this object.','Fixes shadowed names.','this(...) chains constructors first.'],recall:'When do you need this?',todo:'Use this in your Pen constructor.',anim:{title:'Name tag',steps:[{caption:'Two titles: field vs parameter.',html:'<div class="pipe"><div class="box">field: ?</div><div class="box">param: "Dune"</div></div>'},{caption:'this.title picks mine.',html:'<div class="pipe"><div class="box">this.title = "Dune" ✓</div></div>'},{caption:'Field stamped, crowd clears.',html:'<div class="viz"><div class="varbox"><div class="nm">this.title</div><div class="vl">Dune</div></div></div>'}]}},
'encapsulation':{intro:'Hide the engine, show the steering wheel. Private fields + public methods keep objects valid even when callers are careless.',question:'Why can’t bank customers open the vault but can use the ATM?',analogy:'Medicine bottle: child-proof cap (private) + measured spoon (public method). Direct handfuls blocked; safe doses allowed.',analogyFail:'Where it breaks: caps annoy adults too. Encapsulation needs well-designed methods — or users pry the cap (reflection/hacks).',explain:['<b>private</b> fields; <b>public getters/setters</b>: getTitle(), setPages(n) with checks.','<b>Validate inside setters</b>: reject negatives, clamp ranges. One guard protects all callers.','Expose behavior (borrow()), not raw flags.'],code:`class Book {\n  private int pages;\n  public int getPages() { return pages; }\n  public void setPages(int p) {\n    if (p > 0) pages = p;\n  }\n}\nBook b = new Book();\nb.setPages(-5);\nb.setPages(200);\nSystem.out.println(b.getPages());`,codeNotes:['pages hidden.','-5 rejected.','200 accepted.'],output:'200',why:'Setter guards; invalid ignored, valid stored.',sim:{kind:'arith',label:'Guard: try -5 vs 200.',fields:[{v:'200'},{o:['+']},{v:'0'}]},mistakes:[{bad:'public int pages; anyone sets -5',why:'No guard.',fix:'private + setter check.'},{bad:'Setter without check',why:'Pointless wrapper.',fix:'Add if (p > 0).'},{bad:'Getter returning mutable list directly',why:'Callers mutate inside!',fix:'Return copy/unmodifiable.'}],practices:[{title:'Guard age',task:'setAge allows 0..150 only.',hint:'if in range assign.',sol:'if (a>=0 && a<=150) age=a;'},{title:'Read-only?',task:'Make title read-only.',hint:'Getter, no setter.',sol:'private title + getTitle only.'}],quiz:[{id:'q1',prompt:'Encapsulation = ?',options:[{t:'Private data + public safe methods',ok:true},{t:'All public'},{t:'No methods'},{t:'Delete data'}],explain:'Cap + spoon.'},{id:'q2',prompt:'Output above?',options:[{t:'200',ok:true},{t:'-5'},{t:'0'},{t:'Error'}],explain:'-5 rejected.'},{id:'q3',prompt:'Where to validate?',options:[{t:'Inside setters/methods',ok:true},{t:'In every caller'},{t:'Never'},{t:'In comments'}],explain:'One guard, all safe.'}],takeaways:['Hide fields, expose safe actions.','Validate once inside.','Read-only = getter only.'],recall:'What is the “cap” and the “spoon”?',todo:'Privatize Pen fields + add guarded setter.',anim:{title:'Vault + ATM',steps:[{caption:'Vault (private pages) locked.',html:'<div class="pipe"><div class="box">🔒 pages: ?</div></div>'},{caption:'ATM setPages(-5) → denied.',html:'<div class="pipe"><div class="box">-5 ❌ rejected</div></div>'},{caption:'ATM setPages(200) → accepted.',html:'<div class="pipe"><div class="box">200 ✓ stored</div></div>'}]}},
'access-mods':{intro:'Who may enter which room? private (me), package (neighbors), protected (family+neighbors), public (everyone).',question:'Why do diaries have locks but notice boards do not?',analogy:'House: bedroom private, kitchen package (flatmates), family heirloom protected (kids + flatmates), gate public. Start locked, open as needed.',analogyFail:'Where it breaks: locks are social, not vaults (reflection can peek). Design intent, not NSA security.',explain:['<b>private</b>: class only. <b>(default)</b>: package. <b>protected</b>: package + kids. <b>public</b>: all.','Rule: <b>most restrictive that works</b>. Fields private; helpers private; API public.','Packages group neighbors; protected helps inheritance (later).'],code:`class Demo {\n  private int secret = 1;\n  int neighbor = 2;        // package\n  protected int heir = 3;\n  public int open = 4;\n  private void help() {}\n  public void serve() { help(); }\n}`,codeNotes:['secret: class only.','serve public, help private.','Open from strict → loose.'],output:'(design lesson — compiles)',why:'Visibility shapes who can call what; compiler enforces.',sim:{kind:'concat',label:'Least privilege: start locked.',fields:[{v:'private'},{v:' first'}]},mistakes:[{bad:'Everything public',why:'No guards possible.',fix:'Private by default.'},{bad:'private test helper untested',why:'Cannot reach from test...',fix:'Package-private helper for tests.'},{bad:'protected for everything',why:'Overexposed to kids.',fix:'Private unless kids need it.'}],practices:[{title:'Rank it',task:'Order strict→loose: public, private, protected, package.',hint:'Me < neighbors < family < all.',sol:'private, package, protected, public.'},{title:'Choose',task:'Helper used in one class only?',hint:'Tightest.',sol:'private.'}],quiz:[{id:'q1',prompt:'Most restrictive?',options:[{t:'private',ok:true},{t:'public'},{t:'protected'},{t:'package'}],explain:'Class only.'},{id:'q2',prompt:'Default (no word) = ?',options:[{t:'Package neighbors',ok:true},{t:'Public'},{t:'Private only'},{t:'Nobody'}],explain:'Same package.'},{id:'q3',prompt:'Fields should start…',options:[{t:'private',ok:true},{t:'public'},{t:'protected always'},{t:'No modifier thought'}],explain:'Lock first.'}],takeaways:['private < package < protected < public.','Most restrictive that works.','Helpers private; API public.'],recall:'What can “neighbors” (package) see?',todo:'Audit one class: tighten one member.',anim:{title:'House rooms',steps:[{caption:'Bedroom 🔒 private: me only.',html:'<div class="pipe"><div class="box">🔒 secret</div></div>'},{caption:'Kitchen: flatmates (package).',html:'<div class="pipe"><div class="box">🍳 neighbor</div></div>'},{caption:'Gate: everyone (public).',html:'<div class="pipe"><div class="box">🚪 open</div></div>'}]}},
'static-members':{intro:'static belongs to the blueprint, shared by all houses. Counters, constants, Math helpers — one copy for everyone.',question:'What does a colony share vs own privately?',analogy:'Colony park (static, shared) vs home garden (instance, per house). totalBooks counts all; title differs per book. Park litter affects all — shared state risk!',analogyFail:'Where it breaks: parks need no house to visit. Static needs no object — but cannot see instance gardens (no this).',explain:['<b>static int total</b>: one copy. <b>static void</b>: call via ClassName.method(). No object needed.','Use for: constants, pure helpers (Math.max), counters. Avoid mutable shared state.','Static cannot use <b>this</b> or instance fields.'],code:`class Book {\n  static int total = 0;\n  String title;\n  Book(String t) { title = t; total++; }\n}\nnew Book("A"); new Book("B");\nSystem.out.println(Book.total); // 2`,codeNotes:['total shared.','Each birth ++.','Read via class name.'],output:'2',why:'Two objects, one counter incremented twice.',sim:{kind:'arith',label:'Shared counter: add books.',fields:[{v:'1'},{o:['+']},{v:'1'}]},mistakes:[{bad:'this.total in static',why:'No this object!',fix:'Use Book.total.'},{bad:'Mutable static favoritism',why:'Hidden global, tests clash.',fix:'Prefer instance or constants.'},{bad:'book.total (via object)',why:'Works but misleads.',fix:'Book.total (class).'}],practices:[{title:'Call it',task:'Call Math.max(3,9) — object needed?',hint:'Static.',sol:'No: Math.max(3, 9) → 9.'},{title:'Counter',task:'Add static count to Pen.',hint:'++ in constructor.',sol:'static int count; count++ in Pen().' }],quiz:[{id:'q1',prompt:'static means…',options:[{t:'One copy shared by all',ok:true},{t:'Copy per object'},{t:'Deleted'},{t:'Private always'}],explain:'Blueprint-level.'},{id:'q2',prompt:'Output above?',options:[{t:'2',ok:true},{t:'0'},{t:'1'},{t:'Error'}],explain:'Two births.'},{id:'q3',prompt:'Static cannot use…',options:[{t:'this / instance fields',ok:true},{t:'Parameters'},{t:'Locals'},{t:'Constants'}],explain:'No object in scope.'}],takeaways:['Shared: one copy, ClassName.access.','Helpers + constants = great; mutable = risky.','No this in static.'],recall:'Instance vs static: where does each live?',todo:'Add a static counter to a class.',anim:{title:'Park vs garden',steps:[{caption:'Gardens: per house (title).',html:'<div class="pipe"><div class="box">A 🌱</div><div class="box">B 🌿</div></div>'},{caption:'Park: one shared (total).',html:'<div class="viz"><div class="varbox"><div class="nm">total (shared)</div><div class="vl">0 → 2</div></div></div>'},{caption:'Each birth ticks the park sign.',html:'<div class="pipe"><div class="box">new A → 1</div><span class="arr">→</span><div class="box">new B → 2</div></div>'}]}},
'inheritance':{intro:'Children reuse parents: Student is a Person with extras. Write shared code once in the parent.',question:'Why do younger siblings get hand-me-downs?',analogy:'Family wardrobe: parent owns jackets (name, walk()). Child Student extends Person, adds grade, reuses jackets, may tailor (override later). Java: one wardrobe donor only (single inheritance).',analogyFail:'Where it breaks: hand-me-downs may not fit. Child cannot remove parent traits — only add/refine. Wrong “is-a”? Use composition.',explain:['<b>class Student extends Person</b>. Child gets fields/methods (non-private).','<b>super(...)</b> first line builds parent part. <b>super.method()</b> calls parent version.','Java: <b>one parent class</b>, many interfaces. Test: “is-a”? Student is a Person ✓.'],code:`class Person { String name; Person(String n){ name=n; } }\nclass Student extends Person {\n  int grade;\n  Student(String n, int g){ super(n); grade=g; }\n}\nStudent s = new Student("Ada", 90);\nSystem.out.println(s.name + " " + s.grade);`,codeNotes:['Student reuses name.','super builds parent.','Adds grade.'],output:'Ada 90',why:'Parent part + child part assembled in order.',sim:{kind:'concat',label:'Parent + child data.',fields:[{v:'Ada'},{v:', 90'}]},mistakes:[{bad:'Forgetting super(...)',why:'Parent unbuilt (if no no-arg).',fix:'super(n); first line.'},{bad:'Book extends Library (wrong is-a)',why:'Book is-not-a Library.',fix:'Library has Books (composition).'},{bad:'Expecting two parents',why:'Single class inheritance.',fix:'Extend one; implement interfaces.'}],practices:[{title:'Is-a?',task:'Car/Engine: inheritance or not?',hint:'Is engine a car?',sol:'No — composition (has-a).'},{title:'Add Teacher',task:'Teacher extends Person + subject.',hint:'Mirror Student.',sol:'class Teacher extends Person { String subject; ... }'}],quiz:[{id:'q1',prompt:'Student extends Person: Student…',options:[{t:'Reuses Person + adds more',ok:true},{t:'Loses Person traits'},{t:'Has two parents'},{t:'Deletes Person'}],explain:'Add, not remove.'},{id:'q2',prompt:'super(n) does…',options:[{t:'Build parent part first',ok:true},{t:'Call child again'},{t:'Delete parent'},{t:'Print n'}],explain:'Parent construction leads.'},{id:'q3',prompt:'Java class inheritance?',options:[{t:'Single (one parent)',ok:true},{t:'Multiple parents'},{t:'None'},{t:'Unlimited'}],explain:'One extends; many implements.'}],takeaways:['extends reuses parent.','super builds parent first.','Use only for true is-a.'],recall:'When inheritance vs composition?',todo:'Model Animal → Dog with extends.',anim:{title:'Hand-me-downs',steps:[{caption:'Parent wardrobe: name, walk().',html:'<div class="pipe"><div class="box"><b>Person</b><br>name · walk()</div></div>'},{caption:'Child inherits + adds grade.',html:'<div class="pipe"><div class="box"><b>Student</b><br>+ grade · study()</div></div>'},{caption:'super(n) sews parent part first.',html:'<div class="pipe"><div class="box">super → Person</div><span class="arr">→</span><div class="box">+ Student</div></div>'}]}},
'overriding':{intro:'Same signature, new behavior: child tailors the hand-me-down. @Override proves you meant it.',question:'When does a child cook the family curry differently — and say so?',analogy:'Tailor shop: parent jacket speak() says “...”. Child Dog re-cuts it to “Woof!”. Tag @Override = “yes, intentional alteration”. Overloading = same name, new sizes (different inputs) — different shop.',analogyFail:'Where it breaks: tailoring needs same measurements (signature). Different inputs = overload, not override.',explain:['<b>@Override void speak()</b>: same name + inputs + compatible return. Runtime picks child version.','<b>Overload</b>: same name, different inputs (compile-time choice). Keep apart!','Rules: cannot weaken access; static/private do not override.'],code:`class Animal { void speak(){ System.out.println("..."); } }\nclass Dog extends Animal {\n  @Override void speak(){ System.out.println("Woof!"); }\n}\nAnimal a = new Dog();\na.speak(); // Woof!`,codeNotes:['Same signature.','@Override guards typos.','Child version runs.'],output:'Woof!',why:'Dynamic dispatch: object type (Dog) wins over reference type (Animal).',sim:{kind:'concat',label:'Which speak runs?',fields:[{v:'Woof'},{v:'!'}]},mistakes:[{bad:'void speak(String s) “override”',why:'Different inputs = overload!',fix:'Match exactly for override.'},{bad:'Missing @Override + typo speek',why:'Silent new method, bug hides.',fix:'Always @Override.'},{bad:'Reducing public → private',why:'Illegal weakening.',fix:'Keep or widen.'}],practices:[{title:'Overload or override?',task:'speak() vs speak(String): which?',hint:'Inputs differ.',sol:'Overload.'},{title:'Add Cat',task:'Cat speaks Meow via override.',hint:'@Override void speak.',sol:'class Cat extends Animal { @Override void speak(){...} }'}],quiz:[{id:'q1',prompt:'Override needs…',options:[{t:'Same signature, new body',ok:true},{t:'Different inputs'},{t:'New name'},{t:'Static'}],explain:'Same measurements, new cut.'},{id:'q2',prompt:'@Override helps…',options:[{t:'Catch typos at compile',ok:true},{t:'Run faster'},{t:'Hide code'},{t:'Add parents'}],explain:'Intent tag.'},{id:'q3',prompt:'a = new Dog(); a.speak() → ?',options:[{t:'Woof!',ok:true},{t:'...'},{t:'Error'},{t:'Nothing'}],explain:'Object type wins.'}],takeaways:['Override = same shape, new behavior.','Always tag @Override.','Overload ≠ override.'],recall:'What three things must match for override?',todo:'Override toString in a class.',anim:{title:'Tailor',steps:[{caption:'Parent jacket: speak → ...',html:'<div class="pipe"><div class="box">Animal: "..."</div></div>'},{caption:'Child re-cuts: Woof!.',html:'<div class="pipe"><div class="box">Dog: "Woof!" ✂️</div></div>'},{caption:'Wearing Dog → Woof sounds.',html:'<div class="pipe"><div class="box">new Dog → Woof! 🔊</div></div>'}]}},
'polymorphism':{intro:'One remote, many TVs: a common type (Animal) controls different objects (Dog, Cat) — each responds its own way.',question:'How does one “play” button work for songs, videos, and podcasts?',analogy:'Universal remote: button speak() on slot Animal. Insert Dog cartridge → Woof; Cat → Meow. Remote never changes; cartridges vary.',analogyFail:'Where it breaks: remote only has shared buttons. Dog-only trick fetch() needs a Dog remote (cast) — not on Animal.',explain:['<b>Animal a = new Dog();</b> Reference = general, object = specific. Call shared methods; JVM picks the real one.','Enables lists of mixed animals, plug-in behavior, test doubles.','Needs inheritance/interface + override. Compile checks Animal; run uses Dog.'],code:`class Animal { void speak(){ System.out.println("..."); } }\nclass Dog extends Animal {\n  @Override void speak(){ System.out.println("Woof!"); }\n}\nclass Cat extends Animal {\n  @Override void speak(){ System.out.println("Meow!"); }\n}\nAnimal[] zoo = { new Dog(), new Cat() };\nfor (Animal a : zoo) a.speak();`,codeNotes:['One array, two species.','Same call, two sounds.','New animal? Just add cartridge.'],output:'Woof!\nMeow!',why:'Each object’s override runs — one loop, many behaviors.',sim:{kind:'concat',label:'One call, many sounds.',fields:[{v:'Woof'},{v:' + Meow'}]},mistakes:[{bad:'a.fetch() on Animal ref',why:'Button missing on remote.',fix:'Add to Animal or cast to Dog.'},{bad:'“Which runs? Reference type.”',why:'Object type wins!',fix:'new Dog() → Dog.speak.'},{bad:'If-else per type everywhere',why:'Defeats the point.',fix:'Rely on override.'}],practices:[{title:'Add Parrot',task:'Parrot speaks “Squawk” in zoo — change loop?',hint:'No!',sol:'Add class; loop unchanged.'},{title:'Why useful?',task:'One sentence: why one array?',hint:'New types plug in.',sol:'Add species without rewriting loop.'}],quiz:[{id:'q1',prompt:'Animal a = new Dog(); a.speak()?',options:[{t:'Dog version',ok:true},{t:'Animal version'},{t:'Error'},{t:'Random'}],explain:'Object decides.'},{id:'q2',prompt:'Benefit?',options:[{t:'Same code handles new types',ok:true},{t:'Faster typing'},{t:'Fewer classes'},{t:'No overrides'}],explain:'Plug-in power.'},{id:'q3',prompt:'Can you call Dog-only fetch via Animal?',options:[{t:'No — not on the remote',ok:true},{t:'Yes always'},{t:'Sometimes'},{t:'With comments'}],explain:'Shared buttons only.'}],takeaways:['One type, many behaviors.','Object type picks the method.','Add types without rewriting loops.'],recall:'What must exist for polymorphism to work?',todo:'Build Shape → Circle/Square with draw().',anim:{title:'Remote',steps:[{caption:'Slot type: Animal remote.',html:'<div class="pipe"><div class="box">🎮 speak()</div></div>'},{caption:'Insert Dog → Woof.',html:'<div class="pipe"><div class="box">Dog 🐶 → Woof!</div></div>'},{caption:'Insert Cat → Meow, same button.',html:'<div class="pipe"><div class="box">Cat 🐱 → Meow!</div></div>'}]}},
'abstract-classes':{intro:'Half-drawn blueprint: defines some rooms, leaves others as “finish later”. Children must complete them.',question:'Why do exam papers leave blanks instead of full answers?',analogy:'Cake mix box: ready flour+sugar (concrete bake()), blank “add flavor” (abstract flavor()). You cannot serve the mix — bake a VanillaCake child first.',analogyFail:'Where it breaks: mixes expire. Abstracts persist — but you still cannot new them, ever.',explain:['<b>abstract class + abstract void flavor();</b> No body. Child must implement (or stay abstract).','Cannot <b>new</b> abstract. Concrete methods shared; abstract force the varies-part.','Vs interface (next): abstract can hold state + constructors + shared code.'],code:`abstract class Cake {\n  void bake(){ System.out.println("Baking..."); }\n  abstract void flavor();\n}\nclass Vanilla extends Cake {\n  @Override void flavor(){ System.out.println("Vanilla!"); }\n}\nnew Vanilla().flavor();`,codeNotes:['bake shared.','flavor forced.','Vanilla completes it.'],output:'Vanilla!',why:'Child fills the blank; shared bake inherited.',sim:{kind:'concat',label:'Fill the blank flavor.',fields:[{v:'Vanilla'},{v:'!'}]},mistakes:[{bad:'new Cake()',why:'Half-built — forbidden.',fix:'new Vanilla().'},{bad:'Child skips flavor',why:'Stays abstract too.',fix:'Implement or declare abstract.'},{bad:'Abstract for everything',why:'Overkill.',fix:'Abstract only the varies-part.'}],practices:[{title:'Make Shape',task:'abstract draw() + concrete info().',hint:'One each.',sol:'abstract class Shape{ void info(){} abstract void draw(); }'},{title:'Finish Circle',task:'Circle extends Shape, draw prints O.',hint:'@Override.',sol:'class Circle extends Shape{ @Override void draw(){...} }'}],quiz:[{id:'q1',prompt:'Can you new an abstract class?',options:[{t:'No',ok:true},{t:'Yes'},{t:'Sometimes'},{t:'With comments'}],explain:'Incomplete by design.'},{id:'q2',prompt:'Child ignoring abstract method…',options:[{t:'Must also be abstract',ok:true},{t:'Fine, concrete'},{t:'Deletes parent'},{t:'Becomes static'}],explain:'Blank passes down.'},{id:'q3',prompt:'Abstracts can hold…',options:[{t:'State + concrete methods',ok:true},{t:'Nothing'},{t:'Only comments'},{t:'Only statics'}],explain:'Half-built, not empty.'}],takeaways:['Half blueprint; children finish.','Never new abstract.','Shared code + forced blanks.'],recall:'Abstract class vs interface in one line?',todo:'Design an abstract Vehicle with one abstract method.',anim:{title:'Cake mix',steps:[{caption:'Box: bake ready, flavor blank.',html:'<div class="pipe"><div class="box">bake() ✓</div><div class="box">flavor() ___</div></div>'},{caption:'new Cake() blocked 🚫.',html:'<div class="pipe"><div class="box">new Cake() ❌</div></div>'},{caption:'Vanilla fills blank, serves.',html:'<div class="pipe"><div class="box">Vanilla → flavor ✓</div></div>'}]}},
'interfaces':{intro:'Interfaces are pure promises: “can do X” with zero how. A class can sign many — Java’s answer to multiple inheritance.',question:'How can a phone, camera, and drone all “take photos” differently?',analogy:'Plug sockets: shape (method names) fixed, wiring inside varies. Drone, phone, camera all plug into Flyable/Capturable sockets. One device, many sockets.',analogyFail:'Where it breaks: sockets do not power themselves. Interfaces hold no object state (until Java 8 defaults) — behavior contracts only.',explain:['<b>interface Borrowable { void borrow(); }</b> <b>class Book implements Borrowable</b>. Must write all methods.','One class, <b>many interfaces</b>. Many classes, one interface → polymorphism.','Vs abstract: no lineage needed. Use for capabilities (can-fly, can-save).'],code:`interface Speaker { void speak(); }\nclass Robot implements Speaker {\n  public void speak(){ System.out.println("Beep!"); }\n}\nSpeaker s = new Robot();\ns.speak();`,codeNotes:['Promise declared.','Robot signs + delivers.','Use via promise type.'],output:'Beep!',why:'Contract fulfilled; polymorphism via interface.',sim:{kind:'concat',label:'Sign the promise.',fields:[{v:'Beep'},{v:'!'}]},mistakes:[{bad:'Forgetting a method',why:'Contract broken — error.',fix:'Implement all.'},{bad:'Expecting one interface only',why:'Many allowed!',fix:'implements A, B.'},{bad:'new Speaker()',why:'Promise, not a thing.',fix:'new Robot().'}],practices:[{title:'Write Drawable',task:'interface Drawable { void draw(); }',hint:'No body.',sol:'interface Drawable{ void draw(); }'},{title:'Two promises',task:'class D implements A, B — ok?',hint:'Yes!',sol:'Yes — multiple allowed.'}],quiz:[{id:'q1',prompt:'A class can implement…',options:[{t:'Many interfaces',ok:true},{t:'Zero only'},{t:'One max'},{t:'None ever'}],explain:'Many sockets.'},{id:'q2',prompt:'new on interface?',options:[{t:'No — implement first',ok:true},{t:'Yes'},{t:'Sometimes'},{t:'With static'}],explain:'Contract only.'},{id:'q3',prompt:'Use interface for…',options:[{t:'Capability across families',ok:true},{t:'Parent-child reuse only'},{t:'Storing state'},{t:'Deleting code'}],explain:'Can-do promises.'}],takeaways:['Pure can-do contracts.','Many per class.','Enables cross-family polymorphism.'],recall:'When interface vs abstract class?',todo:'Write Playable interface + two implementers.',anim:{title:'Sockets',steps:[{caption:'Socket: speak() shape.',html:'<div class="pipe"><div class="box">🔌 Speaker.speak()</div></div>'},{caption:'Robot plugs in.',html:'<div class="pipe"><div class="box">Robot → Beep!</div></div>'},{caption:'Human plugs in too.',html:'<div class="pipe"><div class="box">Human → Hello!</div></div>'}]}},
'composition':{intro:'Has-a beats is-a when reuse is the goal: a Library has Books; a Car has an Engine. Assemble, do not inherit.',question:'Is a library a kind of book — or a holder of books?',analogy:'Lego castle: walls, gate, tower snapped together. Swap the gate without rebuilding the castle. Inheritance would glue them forever.',analogyFail:'Where it breaks: Lego needs connectors (methods passing calls). For true specialization (Student is Person), inheritance still wins.',explain:['<b>Field of another type</b>: class Library { List<Book> books; }. <b>Delegate</b>: library.add() calls book methods.','Prefer when: reuse code, no is-a, want swap-ability (different Engine).','Test: “is-a”? No → compose.'],code:`class Engine { void start(){ System.out.println("Vroom"); } }\nclass Car {\n  Engine engine = new Engine();\n  void start(){ engine.start(); }\n}\nnew Car().start();`,codeNotes:['Car has Engine.','start delegates.','Swap engine freely.'],output:'Vroom',why:'Composition + delegation: Car asks its part to work.',sim:{kind:'concat',label:'Assemble parts.',fields:[{v:'Car'},{v:' + Engine'}]},mistakes:[{bad:'Car extends Engine',why:'Car is-not-an Engine!',fix:'Car has Engine.'},{bad:'Exposing engine publicly',why:'Callers bypass Car.',fix:'Private + delegate.'},{bad:'Inherit for code reuse only',why:'Fragile hierarchy.',fix:'Compose + delegate.'}],practices:[{title:'Is-a or has-a?',task:'Library/Book: which?',hint:'Holder?',sol:'Has-a → composition.'},{title:'Delegate',task:'Library.borrow(title) delegates to?',hint:'Find book, call borrow.',sol:'book.borrow();'}],quiz:[{id:'q1',prompt:'Library-Book is…',options:[{t:'Composition (has-a)',ok:true},{t:'Inheritance'},{t:'Override'},{t:'Static'}],explain:'Holder, not kind.'},{id:'q2',prompt:'Benefit?',options:[{t:'Swap parts, less coupling',ok:true},{t:'Fewer files'},{t:'Faster typing'},{t:'More parents'}],explain:'Lego swap.'},{id:'q3',prompt:'Car.start above delegates to…',options:[{t:'engine.start()',ok:true},{t:'Nothing'},{t:'super'},{t:'static'}],explain:'Part does work.'}],takeaways:['Has-a → field + delegate.','Swap-able, loosely coupled.','Is-a? inherit. Otherwise compose.'],recall:'Give one inheritance and one composition example.',todo:'Refactor one extends into has-a.',anim:{title:'Lego',steps:[{caption:'Bricks: Engine, Wheels.',html:'<div class="pipe"><div class="box">Engine</div><div class="box">Wheels</div></div>'},{caption:'Snap into Car.',html:'<div class="pipe"><div class="box"><b>Car</b> has Engine + Wheels 🧱</div></div>'},{caption:'Swap engine, castle stands.',html:'<div class="pipe"><div class="box">new Engine 🔄 same Car</div></div>'}]}},
'packages':{intro:'Packages are labeled shelves: com.shop.cart holds Cart classes. Imports borrow from other shelves without name fights.',question:'Why do libraries shelve fiction apart from science?',analogy:'Supermarket aisles: com.shop.cart (carts), com.shop.pay (payments). Two Apples (fruit vs tech)? Aisles disambiguate: fruit.Apple vs tech.Apple.',analogyFail:'Where it breaks: aisles do not lock. Packages organize + gate (package-private); jars still need discipline.',explain:['<b>package com.shop;</b> first line. Folders mirror dots. <b>import java.util.List;</b> borrows.','<b>java.lang</b> auto-imported (String, Math). <b>*</b> imports a shelf (not sub-shelves).','Clash? Use full name: java.util.Date vs java.sql.Date.'],code:`package com.shop;\nimport java.util.ArrayList;\nimport java.util.List;\npublic class Cart {\n  List<String> items = new ArrayList<>();\n}`,codeNotes:['Shelf label first.','Borrow List tools.','Diamond <> infers type.'],output:'(organizes — compiles)',why:'Structure + imports resolve names.',sim:{kind:'concat',label:'Aisle + shelf naming.',fields:[{v:'com.shop'},{v:'.Cart'}]},mistakes:[{bad:'No package, 50 files flat',why:'Name soup.',fix:'Group by feature.'},{bad:'import java.util.*; expecting subpackages',why:'* is shallow.',fix:'Import each shelf.'},{bad:'Two Dates clash',why:'Ambiguous.',fix:'Full name one of them.'}],practices:[{title:'Shelf it',task:'Where does com.shop.Cart live?',hint:'Folders mirror.',sol:'com/shop/Cart.java.'},{title:'Borrow List',task:'Import List + ArrayList.',hint:'java.util.',sol:'import java.util.List; import java.util.ArrayList;'}],quiz:[{id:'q1',prompt:'First line for shelf?',options:[{t:'package com.shop;',ok:true},{t:'import com.shop;'},{t:'shelf com.shop;'},{t:'box com.shop;'}],explain:'Package declares.'},{id:'q2',prompt:'Auto-imported?',options:[{t:'java.lang',ok:true},{t:'java.util'},{t:'All packages'},{t:'None'}],explain:'String, Math free.'},{id:'q3',prompt:'Name clash fix?',options:[{t:'Full name one class',ok:true},{t:'Delete both'},{t:'Rename Java'},{t:'No fix'}],explain:'Disambiguate.'}],takeaways:['Packages = shelves; folders mirror.','import borrows; lang is free.','Full names break ties.'],recall:'What does import * miss?',todo:'Package your project classes properly.',anim:{title:'Aisles',steps:[{caption:'Aisle com.shop.cart.',html:'<div class="pipe"><div class="box">🛒 Cart</div></div>'},{caption:'Aisle com.shop.pay.',html:'<div class="pipe"><div class="box">💳 Pay</div></div>'},{caption:'Borrow: import cart.Cart.',html:'<div class="pipe"><div class="box">import → use ✓</div></div>'}]}},
'exceptions':{intro:'Exceptions are fire alarms: unexpected guests (missing file, bad input) that must be caught, guided out, or announced.',question:'What should a wedding planner do when an uninvited guest arrives?',analogy:'Wedding bouncer: try the party, catch gatecrashers by type (NoSeat vs NoFood), finally clean up. throw = shout “fire!”; throws = sign “may shout”.',analogyFail:'Where it breaks: catching every alarm and napping (empty catch) burns the hall. Handle or escalate honestly.',explain:['<b>try { risky } catch (IOException e) { plan B } finally { cleanup }</b>. Catch specific first.','<b>throw new IllegalArgumentException("age?")</b> signals. <b>throws</b> warns callers.','Flow jumps to catch; finally always runs (even on return).'],code:`try {\n  int age = Integer.parseInt("18");\n  System.out.println("Age " + age);\n} catch (NumberFormatException e) {\n  System.out.println("Type digits please!");\n} finally {\n  System.out.println("Done checking");\n}`,codeNotes:['Risky parse in try.','Bad text → catch plan B.','finally always speaks.'],output:'Age 18\nDone checking',why:'Parse succeeded; catch skipped; finally ran.',sim:{kind:'arith',label:'Parse risk: try numbers.',fields:[{v:'18'},{o:['+']},{v:'0'}]},mistakes:[{bad:'catch (Exception e) {} empty',why:'Swallows fire silently.',fix:'Log + recover or rethrow.'},{bad:'Generic before specific',why:'Unreachable code error.',fix:'Specific → general.'},{bad:'Forgetting cleanup',why:'Files leak.',fix:'finally or try-with-resources.'}],practices:[{title:'Add guard',task:'Wrap parseInt(input) with catch.',hint:'NumberFormatException.',sol:'try{...}catch(NumberFormatException e){...}'},{title:'Finally?',task:'File opened in try — where close?',hint:'Always runs.',sol:'finally (or try-with-resources).'}],quiz:[{id:'q1',prompt:'finally runs…',options:[{t:'Always',ok:true},{t:'On success only'},{t:'On catch only'},{t:'Never'}],explain:'Cleanup guarantee.'},{id:'q2',prompt:'throw vs throws?',options:[{t:'Signal now vs warn callers',ok:true},{t:'Same thing'},{t:'Opposites reversed'},{t:'Loops'}],explain:'Shout vs sign.'},{id:'q3',prompt:'Catch order?',options:[{t:'Specific → general',ok:true},{t:'General → specific'},{t:'Random'},{t:'Alphabetical'}],explain:'Reachable first.'}],takeaways:['try risky, catch specific, finally cleans.','throw signals; throws warns.','Never empty-catch.'],recall:'What jumps where when an exception fires?',todo:'Wrap one parse with try-catch.',anim:{title:'Fire drill',steps:[{caption:'Party in try.',html:'<div class="pipe"><div class="box">🎉 try: parse "18"</div></div>'},{caption:'Crash? catch by type guides out.',html:'<div class="pipe"><div class="box">🚨 catch → plan B</div></div>'},{caption:'finally cleans always.',html:'<div class="pipe"><div class="box">🧹 finally ✓</div></div>'}]}},
'common-exceptions':{intro:'Five usual suspects cause 90% of crashes. Learn their faces and程式 defend before they strike.',question:'What do seatbelts, helmets, and null-checks share?',analogy:'Bouncer photos wall: NullPointer (ghost guest), IndexOutOfBounds (wrong seat), NumberFormat (fake ticket), InputMismatch (wrong currency), FileNotFound (wrong hall). Check ID at the door (validate) — do not fight inside.',analogyFail:'Where it breaks: photos age. New suspects appear — read the exception NAME + line, not memory.',explain:['<b>null</b>: check != null. <b>Index</b>: check 0..len-1. <b>Number</b>: hasNextInt/try-catch.','<b>Validate input</b> ranges; <b>fail fast</b> with clear messages.','Distinguish <b>bug</b> (fix code) vs <b>expected</b> (handle: missing file → default).'],code:`String name = null;\nif (name != null) System.out.println(name.length());\nelse System.out.println("Name missing — using Guest");\nint[] a = {1, 2};\nif (a.length > 5) System.out.println(a[5]);\nelse System.out.println("No seat 5");`,codeNotes:['Null guarded.','Bounds guarded.','Friendly fallbacks.'],output:'Name missing — using Guest\nNo seat 5',why:'Defensive checks convert crashes into messages.',sim:{kind:'array',label:'Guard seats 0-1; try 5.',fields:[{v:'5'}]},mistakes:[{bad:'s.length() hoping non-null',why:'Hope is not a guard.',fix:'if (s != null && !s.isEmpty())'},{bad:'Catching NullPointer to “fix”',why:'Hides the bug.',fix:'Prevent null; fix source.'},{bad:'Cryptic “Error!!”',why:'Unactionable.',fix:'“Age must be 0..150, got -5.”'}],practices:[{title:'Guard it',task:'Guard a[5] on length-2.',hint:'if length > 5.',sol:'if (i >= 0 && i < a.length)...'},{title:'Bug or expected?',task:'Missing user file: bug or handle?',hint:'Users lose files.',sol:'Expected → default + message.'}],quiz:[{id:'q1',prompt:'Null-safe length?',options:[{t:'s != null check first',ok:true},{t:'Try and pray'},{t:'Catch and ignore'},{t:'Delete s'}],explain:'Guard at door.'},{id:'q2',prompt:'Catching NullPointer instead of fixing?',options:[{t:'Bad — hides bug',ok:true},{t:'Great'},{t:'Required'},{t:'Faster'}],explain:'Fix source.'},{id:'q3',prompt:'Good error message…',options:[{t:'States rule + got value',ok:true},{t:'“Error!!”'},{t:'Blank'},{t:'Stack only'}],explain:'Actionable.'}],takeaways:['Know the 5 faces.','Validate at the door.','Bugs fixed; expected handled.'],recall:'Name 3 suspects + their guard.',todo:'Add one guard to your input code.',anim:{title:'Wanted wall',steps:[{caption:'Ghost: null → NPE.',html:'<div class="pipe"><div class="box">👻 null.length() 💥</div></div>'},{caption:'Wrong seat: a[5] → bounds.',html:'<div class="pipe"><div class="box">💺 a[5] on len-2 💥</div></div>'},{caption:'ID check: guard → message ✓.',html:'<div class="pipe"><div class="box">🛡️ check first → safe</div></div>'}]}},
'collections':{intro:'Arrays are fixed trays; collections are smart shelves: lists keep order, sets ban duplicates, maps find by key.',question:'When do you need a queue, a guest-list, or a labeled shelf?',analogy:'Party tools: List = photo queue (order, dupes ok). Set = VIP guest list (unique). Map = coat check ticket → coat (key finds value).',analogyFail:'Where it breaks: coat tickets cost memory + hashing. Tiny fixed data? Array still wins.',explain:['<b>List</b>: ordered, indexed, dupes ok. <b>Set</b>: unique, no index. <b>Map</b>: key→value, keys unique.','Program to <b>interfaces</b>: List<String> l = new ArrayList<>(). Swap later freely.','Equals/hashCode decide uniqueness/keys for objects.'],code:`List<String> queue = List.of("Ada", "Bob", "Ada");\nSet<String> guests = Set.of("Ada", "Bob");\nMap<String, Integer> age = Map.of("Ada", 18);\nSystem.out.println(queue.size() + " " + guests.size() + " " + age.get("Ada"));`,codeNotes:['List keeps dupe Ada.','Set drops dupe.','Map finds by key.'],output:'3 2 18',why:'Same names, three tools, three answers.',sim:{kind:'concat',label:'Key finds value.',fields:[{v:'Ada'},{v:' → 18'}]},mistakes:[{bad:'Set expecting order/index',why:'No index promise.',fix:'Use List for order.'},{bad:'Map with dupe keys expecting two',why:'Keys unique — second wins.',fix:'Check containsKey.'},{bad:'ArrayList<String> everywhere (concrete)',why:'Locked in.',fix:'List<String> l = new ArrayList<>();'}],practices:[{title:'Pick tool',task:'Unique voters? Leaderboard order? Phone→name?',hint:'Set / List / Map.',sol:'Set, List, Map.'},{title:'Dupe keys',task:'put("a",1) then put("a",2): get?',hint:'Last wins.',sol:'2.'}],quiz:[{id:'q1',prompt:'Allows dupes + order?',options:[{t:'List',ok:true},{t:'Set'},{t:'Map keys'},{t:'None'}],explain:'Queue semantics.'},{id:'q2',prompt:'Unique only?',options:[{t:'Set',ok:true},{t:'List'},{t:'Map values'},{t:'Array'}],explain:'Guest list.'},{id:'q3',prompt:'Find by ticket?',options:[{t:'Map',ok:true},{t:'Set'},{t:'List only'},{t:'None'}],explain:'Key→value.'}],takeaways:['List order, Set unique, Map keyed.','Code to interfaces.','Keys unique; values may repeat.'],recall:'Which tool for “no duplicate emails”?',todo:'Store 5 tasks in a List; 3 tags in a Set.',anim:{title:'Party tools',steps:[{caption:'List queue: Ada, Bob, Ada.',html:'<div class="pipe"><div class="box">📋 Ada → Bob → Ada</div></div>'},{caption:'Set list: Ada, Bob (once).',html:'<div class="pipe"><div class="box">✅ Ada · Bob</div></div>'},{caption:'Map ticket Ada → 18.',html:'<div class="pipe"><div class="box">🎟️ Ada → 18</div></div>'}]}},
'arraylist-hashmap':{intro:'Your two daily drivers: ArrayList (growable queue) and HashMap (ticket shelf). Learn 6 methods each and build real apps.',question:'How do you run a canteen line plus a locker room?',analogy:'Canteen tray line (ArrayList: add, get(2), set, remove, size) + locker tickets (HashMap: put, get, containsKey, remove, keySet). Trays shift when one leaves; lockers do not.',analogyFail:'Where it breaks: tray line shifts cost (remove first = move all). Lockers need good tickets (hash) — mutable keys break.',explain:['<b>ArrayList</b>: add, get(i), set(i,v), remove(i), size(). Grows; get fast, front-remove slow.','<b>HashMap</b>: put(k,v), get(k), getOrDefault, containsKey, remove(k), keySet/entrySet. No order promise.','Loop maps via <b>entrySet</b>; never edit while for-each (use iterator/removeIf).'],code:`import java.util.*;\nList<String> line = new ArrayList<>();\nline.add("Ada"); line.add("Bob");\nMap<String, String> locker = new HashMap<>();\nlocker.put("A1", "Ada bag");\nSystem.out.println(line.get(0) + " | " + locker.get("A1"));\nSystem.out.println(line.size() + " " + locker.containsKey("A1"));`,codeNotes:['Growable line.','Ticket shelf.','Size 2, has A1.'],output:'Ada | Ada bag\n2 true',why:'Indexed vs keyed retrieval, both dynamic.',sim:{kind:'array',label:'Line positions 0-1.',fields:[{v:'0'}]},mistakes:[{bad:'line[0] bracket on list',why:'Lists use get()!',fix:'line.get(0).'},{bad:'map.get missing → NPE on unbox',why:'null + int = crash.',fix:'getOrDefault(k, 0).'},{bad:'Remove while for-each',why:'ConcurrentModification!',fix:'removeIf / iterator.'}],practices:[{title:'Queue ops',task:'Add 3, get 2nd, remove 1st, size?',hint:'0-based.',sol:'add×3, get(1), remove(0), size 2.'},{title:'Counter map',task:'Count “a” in list with map.',hint:'getOrDefault+1.',sol:'m.put(w, m.getOrDefault(w,0)+1);'}],quiz:[{id:'q1',prompt:'Growable ordered?',options:[{t:'ArrayList',ok:true},{t:'Array'},{t:'Set'},{t:'Map'}],explain:'Dynamic queue.'},{id:'q2',prompt:'Missing key get returns?',options:[{t:'null',ok:true},{t:'0'},{t:'Error always'},{t:'Empty string'}],explain:'Absent = null.'},{id:'q3',prompt:'Loop k+v via…',options:[{t:'entrySet',ok:true},{t:'Indexes'},{t:'keys only'},{t:'values only'}],explain:'Entries pair.'}],takeaways:['List: add/get/set/remove/size.','Map: put/get/contains/remove.','Missing → null; use getOrDefault.'],recall:'How do you safely count words with a map?',todo:'Build a phonebook map: 3 entries.',anim:{title:'Line + lockers',steps:[{caption:'Line: Ada, Bob join.',html:'<div class="pipe"><div class="box">🧍 Ada → Bob</div></div>'},{caption:'Locker: A1 → Ada bag.',html:'<div class="pipe"><div class="box">🔑 A1 → 🎒</div></div>'},{caption:'get(0) + get("A1") serve.',html:'<div class="pipe"><div class="box">Ada | Ada bag ✓</div></div>'}]}},
'generics':{intro:'Generics are luggage tags: List<String> only carries Strings. Wrong item? Rejected at packing (compile), not at the airport (runtime).',question:'Why label suitcases “books only”?',analogy:'Labeled bins: <String> bin refuses socks at drop-off. Raw bin (no tag) accepts anything — you discover socks at unpacking (ClassCastException).',analogyFail:'Where it breaks: tags wash off at runtime (erasure) — JVM sees plain bins. Tags are compile-time guardians only.',explain:['<b>List<String></b>: declare + <b>new ArrayList<>()</b> diamond. Compiler blocks wrong adds.','No primitives in <>: use <b>Integer, Double, Boolean</b> (autoboxed).','Methods too: <b>static <T> T first(List<T> l)</b>. Bounded: <b><T extends Animal></b>.'],code:`import java.util.*;\nList<String> names = new ArrayList<>();\nnames.add("Ada");\n// names.add(5); // COMPILE ERROR (good!)\nSystem.out.println(names.get(0).length());`,codeNotes:['Tag says Strings.','Wrong add blocked early.','No cast needed on get.'],output:'3',why:'Type-safe: length() known to exist.',sim:{kind:'concat',label:'Tagged bin accepts text.',fields:[{v:'Ada'},{v:' (String ✓)'}]},mistakes:[{bad:'Raw List l = new ArrayList();',why:'No tag — surprises later.',fix:'List<String> l = ...'},{bad:'List<int>',why:'Primitives banned in <>.',fix:'List<Integer>.'},{bad:'Casting from raw: (String) l.get(0)',why:'Manual + risky.',fix:'Tag it; casts vanish.'}],practices:[{title:'Tag it',task:'Fix raw scores list to ints.',hint:'List<Integer>.',sol:'List<Integer> s = new ArrayList<>();'},{title:'Read error',task:'add(5) to List<String>: when caught?',hint:'Packing time.',sol:'Compile time — best kind.'}],quiz:[{id:'q1',prompt:'Generics catch errors…',options:[{t:'At compile time',ok:true},{t:'At runtime only'},{t:'Never'},{t:'In comments'}],explain:'Packing check.'},{id:'q2',prompt:'In <> use…',options:[{t:'Integer (wrapper)',ok:true},{t:'int'},{t:'double'},{t:'char (raw)'}],explain:'Objects only.'},{id:'q3',prompt:'Raw List risk?',options:[{t:'Wrong-type crash later',ok:true},{t:'Faster always'},{t:'No risk'},{t:'Shorter code wins'}],explain:'Sock at unpacking.'}],takeaways:['Tags = compile-time safety.','Diamond <> infers; wrappers for primitives.','Raw = legacy risk.'],recall:'Why do generics beat casting?',todo:'Tag all raw lists in old code.',anim:{title:'Luggage tags',steps:[{caption:'Bin tagged <String>.',html:'<div class="pipe"><div class="box">📦 &lt;String&gt;</div></div>'},{caption:'"Ada" accepted; 5 refused ✋.',html:'<div class="pipe"><div class="box">"Ada" ✓</div><div class="box">5 ❌ compile</div></div>'},{caption:'Unpack: no rummage/cast.',html:'<div class="pipe"><div class="box">get(0).length() ✓</div></div>'}]}},
'enums':{intro:'Enums are fixed menus: MON…SUN, SMALL/MEDIUM/LARGE. No typos, no “monday” vs “Monday” wars.',question:'Why do traffic lights use 3 colors, not words?',analogy:'Signal lights: only RED/YELLOW/GREEN exist. You cannot invent PURPLE. switch on lights is exhaustive — compiler checks you handled all.',analogyFail:'Where it breaks: menus change slowly. Daily specials (user input values) need strings, not enums.',explain:['<b>enum Day { MON, TUE, ... }</b>. Use: <b>Day.MON</b>. Compare with <b>==</b> (safe here!).','Switch exhaustively; add fields/methods: SMALL(250). <b>valueOf("MON")</b> parses.','Prefer over String constants for fixed sets.'],code:`enum Size { SMALL, MEDIUM, LARGE }\nSize s = Size.MEDIUM;\nString msg = switch (s) {\n  case SMALL -> "250ml";\n  case MEDIUM -> "500ml";\n  case LARGE -> "1L";\n};\nSystem.out.println(msg);`,codeNotes:['Fixed choices.','== safe for enums.','Switch covers all.'],output:'500ml',why:'Exact match MEDIUM.',sim:{kind:'concat',label:'Fixed menu pick.',fields:[{v:'MEDIUM'},{v:' → 500ml'}]},mistakes:[{bad:'String "medium" vs "MEDIUM" bugs',why:'Typos slip.',fix:'Use enum.'},{bad:'equals for enums (works but noisy)',why:'== is idiomatic + null-safe-ish.',fix:'s == Size.MEDIUM.'},{bad:'valueOf("medium") crash',why:'Case exact!',fix:'valueOf("MEDIUM") or validate.'}],practices:[{title:'Day enum',task:'enum Day 3 values; pick one.',hint:'UPPER_CASE.',sol:'enum Day{ MON,TUE,WED } Day d=Day.MON;'},{title:'Switch it',task:'Switch Size → price.',hint:'Arrow cases.',sol:'switch(s){case SMALL->...; ...}'}],quiz:[{id:'q1',prompt:'Compare enums with?',options:[{t:'==',ok:true},{t:'equals only'},{t:'='},{t:'~~~'}],explain:'Fixed singletons.'},{id:'q2',prompt:'Enums beat strings because…',options:[{t:'No typos, compiler-checked',ok:true},{t:'Longer'},{t:'Slower'},{t:'Harder'}],explain:'Menu, not free text.'},{id:'q3',prompt:'Output above?',options:[{t:'500ml',ok:true},{t:'250ml'},{t:'1L'},{t:'Error'}],explain:'MEDIUM maps.'}],takeaways:['Fixed sets → enum.','== compares; switch exhausts.','valueOf parses (exact case).'],recall:'When enum vs String?',todo:'Replace 3 string constants with an enum.',anim:{title:'Signals',steps:[{caption:'Only 3 lights exist.',html:'<div class="pipe"><div class="box">🔴</div><div class="box">🟡</div><div class="box">🟢</div></div>'},{caption:'No PURPLE allowed.',html:'<div class="pipe"><div class="box">PURPLE ❌ compile</div></div>'},{caption:'MEDIUM → 500ml.',html:'<div class="pipe"><div class="box">MEDIUM → 500ml ✓</div></div>'}]}},
'files':{intro:'Files remember after power-off. Read configs, save progress — always with auto-closing try-with-resources.',question:'How do you borrow library books without losing them?',analogy:'Library desk: open register (Path), read/write lines, auto-return (try-with-resources closes even on fire). Never leave the register open.',analogyFail:'Where it breaks: registers live at addresses (paths) that differ per computer — use relative paths + handle missing files.',explain:['<b>Files.readString(Path.of("a.txt"))</b>, <b>Files.writeString(...)</b>, <b>readAllLines</b>. <b>Path.of</b> addresses.','<b>try (var in = Files.newBufferedReader(p)) { }</b> auto-closes. Catch <b>IOException/NoSuchFileException</b>.','Text = UTF-8 default; CSV = split(",") per line (simple cases).'],code:`import java.nio.file.*;\nimport java.io.IOException;\ntry {\n  Files.writeString(Path.of("hi.txt"), "Hello file!");\n  String back = Files.readString(Path.of("hi.txt"));\n  System.out.println(back);\n} catch (IOException e) {\n  System.out.println("File trouble: " + e.getMessage());\n}`,codeNotes:['Write then read.','Auto-handled? writeString closes itself.','Missing file → catch, not crash.'],output:'Hello file!',why:'Round-trip through disk with fallback message.',sim:{kind:'concat',label:'Write then read back.',fields:[{v:'Hello '},{v:'file!'}]},mistakes:[{bad:'Scanner(new File) never closed',why:'Leaks handle.',fix:'try (var s = ...) { }'},{bad:'Absolute C:\\ path shared',why:'Breaks on friends’ machines.',fix:'Relative data/hi.txt.'},{bad:'Ignoring IOException',why:'Checked — must handle!',fix:'try-catch or throws.'}],practices:[{title:'Save score',task:'Write "Ada,95" to score.txt.',hint:'writeString.',sol:'Files.writeString(Path.of("score.txt"), "Ada,95");'},{title:'Load safely',task:'Read missing file with fallback.',hint:'Catch NoSuchFile.',sol:'try read; catch → default.'}],quiz:[{id:'q1',prompt:'Auto-close via…',options:[{t:'try-with-resources',ok:true},{t:'Comments'},{t:'finally never'},{t:'System.exit'}],explain:'Closes even on throw.'},{id:'q2',prompt:'Missing file throws…',options:[{t:'NoSuchFileException (an IOException)',ok:true},{t:'NullPointer'},{t:'Nothing'},{t:'Success'}],explain:'Handle it.'},{id:'q3',prompt:'Paths should be…',options:[{t:'Relative + handled',ok:true},{t:'Absolute C:\\ always'},{t:'Hardcoded secrets'},{t:'Random'}],explain:'Portable.'}],takeaways:['NIO Files for text made easy.','Auto-close everything.','Handle missing files kindly.'],recall:'What closes in try-with-resources?',todo:'Save + reload one setting in a file.',anim:{title:'Library desk',steps:[{caption:'Open register (Path).',html:'<div class="pipe"><div class="box">📖 hi.txt</div></div>'},{caption:'Write + read lines.',html:'<div class="pipe"><div class="box">write → read ✓</div></div>'},{caption:'Auto-return even on fire.',html:'<div class="pipe"><div class="box">try(...) → closed 🧹</div></div>'}]}},
'unit-testing':{intro:'Unit tests are robot taste-testers: feed known input, check expected vs actual. Green = safe to change code.',question:'Why do chefs taste with a spoon instead of serving blindly?',analogy:'Taste spoon: recipe add(2,3) must taste 5. @Test writes the spoon; assertEquals(expected, actual) sips. Red spoon → fix recipe, not the spoon.',analogyFail:'Where it breaks: spoons test one dish. 100% spoons ≠ no bugs — also test edges (0, negatives, empty).',explain:['<b>@Test void adds() { assertEquals(5, add(2,3)); }</b> JUnit 5 + import static Assertions.*.','<b>Expected first, actual second</b>. Name tests like sentences: rejectsNegativeAge.','Run via IDE/Maven; red → read message (expected 5 but was 4 at line X).'],code:`// Calculator.java\nstatic int add(int a, int b){ return a + b; }\n// CalculatorTest.java\nimport static org.junit.jupiter.api.Assertions.*;\nimport org.junit.jupiter.api.Test;\nclass CalculatorTest {\n  @Test void adds(){ assertEquals(5, add(2, 3)); }\n  @Test void zero(){ assertEquals(3, add(3, 0)); }\n}`,codeNotes:['Two tiny checks.','Expected vs actual order.','Edge zero covered.'],output:'2 tests, green ✓',why:'Known answers guard future edits.',sim:{kind:'arith',label:'Taste: 2 + 3 must be 5.',fields:[{v:'2'},{o:['+']},{v:'3'}]},mistakes:[{bad:'assertEquals(actual, expected) swapped',why:'Confusing message.',fix:'Expected first!'},{bad:'No edge tests',why:'Happy path only.',fix:'Add 0, empty, negative.'},{bad:'Testing with prints, not asserts',why:'Human must eyeball.',fix:'Assert; robot judges.'}],practices:[{title:'Write one',task:'Test square(4) == 16.',hint:'assertEquals(16, square(4)).',sol:'@Test void sq(){ assertEquals(16, square(4)); }'},{title:'Edge it',task:'Add test: add(-2, 2) == 0.',hint:'Negatives.',sol:'assertEquals(0, add(-2, 2));'}],quiz:[{id:'q1',prompt:'assertEquals order?',options:[{t:'Expected, actual',ok:true},{t:'Actual, expected'},{t:'Random'},{t:'Actual only'}],explain:'Message reads right.'},{id:'q2',prompt:'Green tests mean…',options:[{t:'Checked cases pass (not bug-free)',ok:true},{t:'Zero bugs ever'},{t:'No need to run again'},{t:'Code deleted'}],explain:'Spoons, not proof.'},{id:'q3',prompt:'Best test name?',options:[{t:'rejectsNegativeAge',ok:true},{t:'test1'},{t:'stuff'},{t:'x'}],explain:'Sentence names.'}],takeaways:['Robots check known answers.','Expected first; edges included.','Red → read, fix code.'],recall:'What does a failing test tell you exactly?',todo:'Write 2 tests for your add/square method.',anim:{title:'Taste spoons',steps:[{caption:'Spoon 1: add(2,3) → 5?',html:'<div class="pipe"><div class="box">expect 5, got 5 🟢</div></div>'},{caption:'Spoon 2: add(3,0) → 3?',html:'<div class="pipe"><div class="box">expect 3, got 3 🟢</div></div>'},{caption:'All green → serve safely.',html:'<div class="pipe"><div class="box">2/2 green ✓</div></div>'}]}},
'maven-structure':{intro:'Maven is your project manager: standard shelves, one recipe card (pom.xml), fetches ingredients (JUnit) automatically.',question:'Why do all supermarkets shelve milk similarly?',analogy:'Standard store: src/main/java (fresh food), src/test/java (taste spoons), pom.xml (shopping list). mvn test = “taste everything”. New clerk finds milk instantly.',analogyFail:'Where it breaks: managers need the list. Delete pom.xml → no ingredients, no build. Commit it!',explain:['Layout: <b>src/main/java/com/shop/App.java</b>, tests mirror, <b>pom.xml</b> names deps.','<b><dependency> junit-jupiter</dependency></b> fetches tests. <b>mvn test / package</b> builds.','GroupId = your aisle (com.shop), artifact = product (tasks).'],code:`<!-- pom.xml (essentials) -->\n<project>\n  <groupId>com.shop</groupId>\n  <artifactId>tasks</artifactId>\n  <version>1.0</version>\n  <properties><maven.compiler.release>17</maven.compiler.release></properties>\n  <dependencies>\n    <dependency>\n      <groupId>org.junit.jupiter</groupId>\n      <artifactId>junit-jupiter</artifactId>\n      <version>5.10.0</version>\n      <scope>test</scope>\n    </dependency>\n  </dependencies>\n</project>`,codeNotes:['Java 17 pinned.','JUnit fetched.','Scope test = spoons only.'],output:'mvn test → green',why:'Standard layout + declared deps = reproducible build.',sim:{kind:'concat',label:'Aisle + product naming.',fields:[{v:'com.shop'},{v:':tasks'}]},mistakes:[{bad:'Code in random folders',why:'Nobody finds milk.',fix:'Follow src/main/java.'},{bad:'JUnit jar emailed',why:'Version chaos.',fix:'Declare in pom; Maven fetches.'},{bad:'Java 8 default + var errors',why:'Old release.',fix:'maven.compiler.release 17.'}],practices:[{title:'Shelve it',task:'Where does com.shop.App go?',hint:'Mirror dots.',sol:'src/main/java/com/shop/App.java.'},{title:'Add dep',task:'Add JUnit scope test.',hint:'Copy block.',sol:'Dependency above with <scope>test</scope>.'}],quiz:[{id:'q1',prompt:'Main code lives…',options:[{t:'src/main/java',ok:true},{t:'Anywhere'},{t:'pom.xml'},{t:'Desktop'}],explain:'Standard shelf.'},{id:'q2',prompt:'pom.xml is…',options:[{t:'Shopping list (deps + build)',ok:true},{t:'Java code'},{t:'Test report'},{t:'Image'}],explain:'Recipe card.'},{id:'q3',prompt:'Get JUnit via…',options:[{t:'Declare dependency, run Maven',ok:true},{t:'Email jar'},{t:'Copy random jar'},{t:'No setup'}],explain:'Managed ingredients.'}],takeaways:['Standard shelves find fast.','pom declares + fetches.','Pin Java 17.'],recall:'What two shelves mirror each other?',todo:'Lay out one Maven skeleton locally.',anim:{title:'Store map',steps:[{caption:'Fresh food: src/main/java.',html:'<div class="pipe"><div class="box">🥬 main code</div></div>'},{caption:'Spoons: src/test/java.',html:'<div class="pipe"><div class="box">🥄 tests</div></div>'},{caption:'List: pom.xml fetches.',html:'<div class="pipe"><div class="box">📋 pom → JUnit ✓</div></div>'}]}},
'conventions':{intro:'Readable code is kind code: clear names, small methods, tidy format. Future teammates (and you) read 10× more than write.',question:'Why do road signs share colors and shapes?',analogy:'Road rules: camelCase streets (userAge), PascalCase cities (TaskManager), UPPER roads (MAX_SIZE), braces like lane lines. google-java-format = self-driving painter.',analogyFail:'Where it breaks: paint does not fix potholes (logic). Format + names help; tests prove.',explain:['<b>Names</b>: variables/methods camelCase, classes PascalCase, constants UPPER. Booleans ask: isEmpty, canBorrow.','<b>Small methods</b> (<20 lines), one job, early returns. <b>Format</b>: 2/4 spaces, braces always.','<b>Comments</b> why; delete dead code; no magic numbers.'],code:`// murky vs maintainable\n// int d; // days? dollars?\nint daysUntilTrip = 7;\nboolean canBorrow(Book b) {\n  if (b == null) return false;\n  return b.isAvailable();\n}`,codeNotes:['Name tells all.','Guard first, flat logic.','No mystery d.'],output:'(style — reads clean)',why:'Names + tiny methods explain themselves.',sim:{kind:'concat',label:'Name hygiene check.',fields:[{v:'daysUntilTrip'},{v:' = 7'}]},mistakes:[{bad:'int d, x2, tmp everywhere',why:'Riddles.',fix:'daysUntilTrip, retryCount.'},{bad:'80-line method',why:'Untestable maze.',fix:'Extract 3 helpers.'},{bad:'Commented-out corpses',why:'Rot.',fix:'Delete; git keeps history.'}],practices:[{title:'Rename',task:'Rename boolean f (file exists?).',hint:'Asks a question.',sol:'boolean fileExists;'},{title:'Split it',task:'Split print+save+email method.',hint:'3 helpers.',sol:'printBill(), saveBill(), emailBill().'}],quiz:[{id:'q1',prompt:'Class naming?',options:[{t:'PascalCase (TaskManager)',ok:true},{t:'camelCase'},{t:'UPPER'},{t:'lowercase'}],explain:'Cities capitalized.'},{id:'q2',prompt:'Boolean naming?',options:[{t:'Asks: isEmpty, canBorrow',ok:true},{t:'Nouns only'},{t:'Single letters'},{t:'Numbers'}],explain:'Questions read well.'},{id:'q3',prompt:'Method size?',options:[{t:'Small, one job',ok:true},{t:'80+ lines fine'},{t:'Whole app'},{t:'No methods'}],explain:'Testable pieces.'}],takeaways:['Names teach; format guides.','Small methods, early returns.','Delete dead code.'],recall:'What three naming cases for what?',todo:'Format + rename one old file.',anim:{title:'Road signs',steps:[{caption:'Streets camelCase.',html:'<div class="pipe"><div class="box">userAge 🛣️</div></div>'},{caption:'Cities PascalCase.',html:'<div class="pipe"><div class="box">TaskManager 🏙️</div></div>'},{caption:'Highways UPPER.',html:'<div class="pipe"><div class="box">MAX_SIZE 🛣️</div></div>'}]}},
};
